import openpyxl
from openpyxl.styles import Font, Alignment

wb = openpyxl.load_workbook('init.xlsx')
ws = wb['Sheet1']

# 1. Convert text-stored formulas back to real formulas in D, E, F
for r in range(1, 87):
    for c in [4, 5, 6]:
        cell = ws.cell(r, c)
        if cell.value is not None and isinstance(cell.value, str) and cell.value.startswith('='):
            cell.value = '=B{0}+C{0}'.format(r) if c == 4 else '=D{0}+E{0}'.format(r)

# 2. Set number formats on D, E, F
for r in range(1, 87):
    for c in [4, 5, 6]:
        cell = ws.cell(r, c)
        if cell.value is not None:
            cell.number_format = '##0.0' if cell.value != 0 else '##0'

# 3. Set bold + center on D, E, F
for r in range(1, 87):
    for c in [4, 5, 6]:
        cell = ws.cell(r, c)
        cell.font = Font(bold=True)
        cell.alignment = Alignment(horizontal='center')

# 4. Detect blocks (separated by blank rows) and sort each block by D descending
blocks = []
current = []
for r in range(1, 87):
    if ws.cell(r, 1).value is None:
        if current:
            blocks.append(current)
            current = []
    else:
        current.append(r)
if current:
    blocks.append(current)

for block in blocks:
    block.sort(key=lambda r: ws.cell(r, 4).value, reverse=True)
    for i, r in enumerate(block):
        for c in range(1, 9):
            ws.cell(r, c).value = ws.cell(block[i], c).value

wb.save('output.xlsx')
print('done')
EOF
